#include <stdio.h>
#include <stdlib.h>

void add_edge(int u, int v, int *head, int *to, int *next, int *idx) {
    to[*idx] = v;
    next[*idx] = head[u];
    head[u] = (*idx)++;
}

int bfs(int n, int *head, int *to, int *next, int start, int *dist, int *parent, int *queue) {
    for (int i = 1; i <= n; ++i) {
        dist[i] = -1;
        parent[i] = -1;
    }

    int front = 0, back = 0;
    queue[back++] = start;
    dist[start] = 0;
    int far = start;

    while (front < back) {
        int u = queue[front++];
        if (dist[u] > dist[far]) far = u;

        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                queue[back++] = v;
            }
        }
    }

    return far;
}

int get_center(int n, int *head, int *to, int *next) {
    int *dist = (int*)malloc((n + 1) * sizeof(int));
    int *parent = (int*)malloc((n + 1) * sizeof(int));
    int *queue = (int*)malloc((n + 1) * sizeof(int));

    int a = bfs(n, head, to, next, 1, dist, parent, queue);
    int b = bfs(n, head, to, next, a, dist, parent, queue);

    int D = dist[b];
    int steps = D - D / 2;
    int cur = b;
    for (int i = 0; i < steps; ++i) {
        cur = parent[cur];
    }

    free(dist);
    free(parent);
    free(queue);
    return cur;
}

